@import "tailwindcss";

@theme {
  --font-sans: "SF Pro Display", "Helvetica Neue", "Segoe UI", system-ui, sans-serif;
  --font-serif: "Newsreader", "Lyon Text", Georgia, serif;
  --font-mono: "SF Mono", "JetBrains Mono", ui-monospace, monospace;
}

/* Warm monochrome palette (minimalist-ui). Semantic colors switch with the theme. */
:root {
  --bg: #fbfbfa;
  --surface: #ffffff;
  --surface-2: #f9f9f8;
  --border: #eaeaea;
  --text: #2f3437;
  --muted: #787774;
  --accent: #3f7a74;
  --accent-strong: #2e6b5f;
  --danger: #9f2f2d;
  --focus: #3f7a74;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}

[data-theme="dark"] {
  --bg: #131416;
  --surface: #1c1e21;
  --surface-2: #232529;
  --border: #2e3135;
  --text: #e8e7e4;
  --muted: #9a9a96;
  --accent: #5fb3a8;
  --accent-strong: #6fc3b8;
  --danger: #e08785;
  --focus: #5fb3a8;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}

/* Only color surfaces transitions — never layout. */
.theme-transition {
  transition: background-color 320ms ease, color 320ms ease, border-color 320ms ease;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 6px;
}

/* --- Motion (gated behind prefers-reduced-motion) --- */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  .reveal {
    opacity: 1 !important;
    transform: none !important;
  }
}

.reveal {
  opacity: 0;
  transform: translateY(12px);
}
@media (prefers-reduced-motion: no-preference) {
  .reveal {
    animation: reveal 620ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
  }
  @keyframes reveal {
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

/* Gentle check animation on tap */
.check-pop {
  transform: scale(0.86);
}
@media (prefers-reduced-motion: no-preference) {
  .check-pop {
    animation: pop 240ms cubic-bezier(0.16, 1, 0.3, 1);
  }
  @keyframes pop {
    0% {
      transform: scale(0.6);
    }
    to {
      transform: scale(1);
    }
  }
}

/* Staggered list reveal */
.stagger {
  animation-delay: calc(var(--i, 0) * 70ms);
}

// Datums-Helfer (lokale Tage, deutsch).

/** Lokaler Tag als YYYY-MM-DD (ohne Zeitzone, rein kalenderbasiert). */
export function todayLocal(): string {
  const d = new Date()
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

function pad(n: number): string {
  return String(n).padStart(2, '0')
}

/** YYYY-MM-DD -> vollständiges deutsches Datum, z. B. "Samstag, 24. Oktober 2026". */
export function fmtDateLocal(date: string): string {
  const [y, m, d] = date.split('-').map(Number)
  const dt = new Date(y, m - 1, d)
  return dt.toLocaleDateString('de-DE', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  })
}

/** Kurzer Wochentag, z. B. "Sa". */
export function fmtWeekdayShort(date: string): string {
  const [y, m, d] = date.split('-').map(Number)
  const dt = new Date(y, m - 1, d)
  return dt.toLocaleDateString('de-DE', { weekday: 'short' })
}

/** Tag-Index ( Tage seit 1970 ), für consecutive-Vergleiche. */
export function dayIndex(date: string): number {
  const [y, m, d] = date.split('-').map(Number)
  return Math.round(Date.UTC(y, m - 1, d) / 86400000)
}

export function isNextDay(a: string, b: string): boolean {
  return dayIndex(a) - dayIndex(b) === 1
}

/** Vorheriger Tag als YYYY-MM-DD. */
export function dayBefore(date: string): string {
  const [y, m, d] = date.split('-').map(Number)
  const dt = new Date(y, m - 1, d - 1)
  return `${dt.getFullYear()}-${pad(dt.getMonth() + 1)}-${pad(dt.getDate())}`
}

/** Die letzten 7 Tage, vom ältesten zum heutigen (für das Wochen-Chart). */
export function last7Days(): string[] {
  const today = todayLocal()
  const days: string[] = []
  let d = today
  for (let i = 0; i < 7; i++) days.push(d)
  for (let i = days.length - 1; i > 0; i--) {
    days[i - 1] = dayBefore(days[i])
  }
  return days
}

export function isSameDay(a: string, b: string): boolean {
  return a === b
}

// Streak-Logik: aktuelle und längste Serie pro Habit.

export interface Streaks {
  current: number
  longest: number
}

/**
 * Aktuelle Serie: aufeinanderfolgende Tage, rückwärts ab `today`,
 * in denen der Habit erledigt war. Ist heute erledigt, ist current >= 1.
 */
export function currentStreak(completionDates: string[], today: string): number {
  const set = new Set(completionDates)
  let count = 0
  let d = today
  while (set.has(d)) {
    count += 1
    d = dayBefore(d)
  }
  return count
}

/** Längste aufeinanderfolgende Serie in der gesamten Historie. */
export function longestStreak(completionDates: string[]): number {
  const sorted = [...new Set(completionDates)].sort()
  let longest = 0
  let run = 0
  let prev: string | null = null
  for (const d of sorted) {
    if (prev && isNextDay(d, prev)) {
      run += 1
    } else {
      run = 1
    }
    if (run > longest) longest = run
    prev = d
  }
  return longest
}

export function computeStreaks(completionDates: string[], today: string): Streaks {
  return {
    current: currentStreak(completionDates, today),
    longest: longestStreak(completionDates),
  }
}

// --- Datumshelfer (lokal, kalenderbasiert) ---

export function dayIndex(date: string): number {
  const [y, m, d] = date.split('-').map(Number)
  return Math.round(Date.UTC(y, m - 1, d) / 86400000)
}

export function isNextDay(a: string, b: string): boolean {
  return dayIndex(a) - dayIndex(b) === 1
}

export function dayBefore(date: string): string {
  const [y, m, d] = date.split('-').map(Number)
  const dt = new Date(y, m - 1, d - 1)
  return `${dt.getFullYear()}-${pad(dt.getMonth() + 1)}-${pad(dt.getDate())}`
}

function pad(n: number): string {
  return String(n).padStart(2, '0')
}

// Streak-Logik: aktuelle und längste Serie pro Habit.
