// Zurückhaltende, warme Akzentfarben für Habits.
// `light`/`dark` sind die pro Mode verwendete Farbe (je WCAG AA auf dem jeweiligen Hintergrund),
// `soft`/`softDark` sind die dezenten Chip-Hintergründe.
export interface HabitColor {
  id: string
  label: string
  light: string
  dark: string
  soft: string
  softDark: string
}

export const HABIT_COLORS: HabitColor[] = [
  { id: 'teal', label: 'Teal', light: '#2e6b5f', dark: '#6fc3b8', soft: '#edf3ec', softDark: '#162a27' },
  { id: 'blue', label: 'Blau', light: '#1f6c9f', dark: '#74b8e6', soft: '#e1f3fe', softDark: '#142333' },
  { id: 'amber', label: 'Bernstein', light: '#956400', dark: '#d9a75c', soft: '#fbf3db', softDark: '#2a2113' },
  { id: 'red', label: 'Rot', light: '#9f2f2d', dark: '#e08785', soft: '#fdebec', softDark: '#2e1a19' },
  { id: 'purple', label: 'Violett', light: '#6b4aa5', dark: '#c0a2e6', soft: '#f0e9f7', softDark: '#221a33' },
  { id: 'rose', label: 'Rose', light: '#9f3d6b', dark: '#e09cc0', soft: '#fde7ef', softDark: '#2e1823' },
  { id: 'slate', label: 'Schiefer', light: '#4a5568', dark: '#a0a8b4', soft: '#e9ecf0', softDark: '#1e2229' },
  { id: 'moss', label: 'Moos', light: '#4c7a4a', dark: '#9fd39a', soft: '#eaf2e6', softDark: '#182a17' },
]

export function getColor(id: string): HabitColor {
  return HABIT_COLORS.find((c) => c.id === id) ?? HABIT_COLORS[0]
}

/** Akzentfarbe für SVG-Fills (Recharts), je aktuellem Theme. */
export function accentHex(effectiveTheme: 'light' | 'dark'): string {
  return effectiveTheme === 'dark' ? getColor('teal').dark : getColor('teal').light
}

// Datenschicht: IndexedDB über `idb`. Alles lokal, kein Backend.
import { openDB, DBSchema, IDBPDatabase } from 'idb'
import type { Habit, Completion, Mood, Settings } from './types'

const DB_NAME = 'rhythm-db'
const DB_VERSION = 1

interface RhythmSchema extends DBSchema {
  habits: {
    key: string
    value: Habit
  }
  completions: {
    key: string
    value: Completion
    indexes: { byHabit: string }
  }
  moods: {
    key: string
    value: Mood
  }
  meta: {
    key: string
    value: Settings
  }
}

type DB = IDBPDatabase<RhythmSchema>

let dbPromise: Promise<DB> | null = null

export function getDB(): Promise<DB> {
  if (!dbPromise) {
    dbPromise = openDB(Rhythm_NAME, DB_VERSION, {
      upgrade(db) {
        db.createObjectStore('habits', { keyPath: 'id' })
        const comp = db.createObjectStore('completions', { keyPath: 'id' })
        comp.createIndex('byHabit', 'habitId')
        db.createObjectStore('moods', { keyPath: 'date' })
        db.createObjectStore('meta', { keyPath: 'key' })
      },
    })
  }
  return dbPromise
}

// --- Habits ---
export async function loadHabits(): Promise<Habit[]> {
  const db = await getDB()
  return db.getAll('habits')
}

export async function saveHabit(h: Habit): Promise<void> {
  const db = await getDB()
  await db.put('habits', h)
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await getDB()
  await db.delete('habits', id)
  // Entferne auch die zugehörigen Erledigungen.
  const comps = await db.getAllFromIndex('completions', 'byHabit', id)
  await db.transaction('completions', 'readwrite').store.deleteAllFromIndex('byHabit', id)
  // Falls deleteAllFromIndex nicht verfügbar, lösche über die Einträge.
  for (const c of comps) await db.delete('completions', c.id)
}

// --- Completions ---
export async function loadCompletions(): Promise<Completion[]> {
  const db = await getDB()
  return db.getAll('completions')
}

export async function toggleCompletion(habitId: string, date: string): Promise<void> {
  const db = await getDB()
  const tx = db.transaction(['completions'], 'readwrite')
  const id = `${habitId}_${date}`
  const existing = await tx.store.get(id)
  if (existing) {
    await tx.store.delete(id)
  } else {
    await tx.store.put({ id, habitId, date })
  }
  await tx.done
}

// --- Moods ---
export async function loadMoodsSince(date: string): Promise<Mood[]> {
  const db = await getDB()
  return db.getAll('moods')
}

export async function saveMood(m: Mood): Promise<void> {
  const db = await getDB()
  await db.put('moods', m)
}

// --- Settings ---
export async function loadSettings(): Promise<Settings | undefined> {
  const db = await getDB()
  return db.get('meta', 'settings')
}

export async function saveSettings(s: Settings): Promise<void> {
  const db = await getDB()
  await db.put('meta', s)
